using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using System.Windows.Forms;
using Microsoft.Win32;

namespace BF4Bots {
public static class InstallPath {
 public static readonly string[] ClientFiles={"config.txt","BF4Launcher.exe","bf4_no_drm.exe"};
 static string Saved {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"BF4BotLauncher","game-folder.txt");}}
 public static string[] Missing(string folder){return ClientFiles.Where(file=>!File.Exists(Path.Combine(folder,file))).ToArray();}
 public static string Choose(IEnumerable<string> folders){var candidates=folders.Where(p=>!String.IsNullOrWhiteSpace(p)&&Directory.Exists(p)).Select(Path.GetFullPath).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();return candidates.FirstOrDefault(p=>Missing(p).Length==0)??candidates.FirstOrDefault(p=>File.Exists(Path.Combine(p,"bf4.exe"))||File.Exists(Path.Combine(p,"bf4_no_drm.exe")));}
 public static IEnumerable<string> Libraries(string text){foreach(Match match in Regex.Matches(text??"","\"path\"\\s*\"([^\"]+)\"",RegexOptions.IgnoreCase)){string path=match.Groups[1].Value.Replace("\\\\","\\");if(Path.IsPathRooted(path))yield return path;}}
 static IEnumerable<string> Candidates(){var paths=new List<string>{AppDomain.CurrentDomain.BaseDirectory};try{if(File.Exists(Saved))paths.Add(File.ReadAllText(Saved).Trim());}catch(IOException){}var steamRoots=new List<string>();foreach(string key in new[]{@"HKEY_CURRENT_USER\Software\Valve\Steam",@"HKEY_LOCAL_MACHINE\SOFTWARE\WOW6432Node\Valve\Steam"})foreach(string value in new[]{"SteamPath","InstallPath"}){var path=Registry.GetValue(key,value,null) as string;if(!String.IsNullOrWhiteSpace(path))steamRoots.Add(path);}steamRoots.Add(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),"Steam"));foreach(var drive in DriveInfo.GetDrives().Where(d=>d.IsReady&&d.DriveType==DriveType.Fixed)){steamRoots.Add(Path.Combine(drive.RootDirectory.FullName,"SteamLibrary"));steamRoots.Add(Path.Combine(drive.RootDirectory.FullName,"Steam"));}foreach(var steam in steamRoots.Distinct(StringComparer.OrdinalIgnoreCase).ToArray()){try{string file=Path.Combine(steam,"steamapps","libraryfolders.vdf");if(File.Exists(file))steamRoots.AddRange(Libraries(File.ReadAllText(file)));}catch(IOException){}catch(UnauthorizedAccessException){}}foreach(string steam in steamRoots.Distinct(StringComparer.OrdinalIgnoreCase))foreach(string name in new[]{"Battlefield 4","Battlefield4"})paths.Add(Path.Combine(steam,"steamapps","common",name));paths.Add(@"C:\Program Files\EA Games\Battlefield 4");return paths;}
 public static string Resolve(string[] args){int explicitIndex=Array.IndexOf(args,"--game");string selected=explicitIndex>=0&&explicitIndex+1<args.Length?Path.GetFullPath(args[explicitIndex+1]):Choose(Candidates());if(selected!=null&&(Missing(selected).Length==0||File.Exists(Path.Combine(selected,"bf4.exe")))&&!args.Contains("--choose-game")){Remember(selected);return selected;}using(var dialog=new InstallFolderDialog(selected)){if(dialog.ShowDialog()!=DialogResult.OK)return null;Remember(dialog.Folder);return dialog.Folder;}}
 static void Remember(string path){try{Directory.CreateDirectory(Path.GetDirectoryName(Saved));File.WriteAllText(Saved,path);}catch(IOException){}catch(UnauthorizedAccessException){}}
}
public sealed class InstallFolderDialog : Form {
 TextBox path;Label explanation;Button use;public string Folder {get{return path.Text;}}
 public InstallFolderDialog(string initial){Text="BF4 • Localizar instalação";Font=Theme.Body;ForeColor=Theme.Ink;BackColor=Theme.Background;ClientSize=new Size(760,380);MinimumSize=new Size(650,400);StartPosition=FormStartPosition.CenterScreen;AutoScaleMode=AutoScaleMode.Dpi;var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(24),ColumnCount=1,RowCount=5};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,48));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,38));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,45));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,45));Controls.Add(layout);layout.Controls.Add(new Label{Text="Onde está o seu Battlefield 4?",Font=Theme.Heading,AutoSize=true},0,0);path=new TextBox{Text=initial??"",ReadOnly=true,Dock=DockStyle.Fill,AccessibleName="Pasta selecionada do Battlefield 4"};layout.Controls.Add(path,0,1);var browse=ControlButton("Selecionar pasta…");browse.Click+=(s,e)=>{using(var picker=new FolderBrowserDialog{Description="Selecione a pasta Battlefield 4 dentro de steamapps\\common ou da sua biblioteca.",SelectedPath=Directory.Exists(path.Text)?path.Text:""})if(picker.ShowDialog(this)==DialogResult.OK){path.Text=picker.SelectedPath;RefreshState();}};layout.Controls.Add(browse,0,2);explanation=new Label{Dock=DockStyle.Fill,AutoSize=false,AccessibleName="Compatibilidade da instalação"};layout.Controls.Add(explanation,0,3);var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};use=ControlButton("Usar esta pasta");use.DialogResult=DialogResult.OK;buttons.Controls.Add(use);var cancel=ControlButton("Cancelar");cancel.DialogResult=DialogResult.Cancel;buttons.Controls.Add(cancel);layout.Controls.Add(buttons,0,4);AcceptButton=use;CancelButton=cancel;RefreshState();}
 static Button ControlButton(string text){var button=new Button{Text=text,Width=180,Height=36,FlatStyle=FlatStyle.Flat,BackColor=Theme.Surface,ForeColor=Theme.Ink,Margin=new Padding(4),Cursor=Cursors.Hand};button.FlatAppearance.BorderColor=Theme.Border;return button;}
 void RefreshState(){var missing=InstallPath.Missing(path.Text);use.Enabled=Directory.Exists(path.Text)&&(missing.Length==0||File.Exists(Path.Combine(path.Text,"bf4.exe")));explanation.Text=use.Enabled?"Pasta do BF4 localizada. O assistente verificará o cliente e poderá instalar o mod do seu pacote local.":String.IsNullOrWhiteSpace(path.Text)?"Selecione a pasta do jogo. As bibliotecas Steam são procuradas automaticamente.":"Pasta selecionada: "+path.Text+"\r\n\r\nComponentes do cliente offline não encontrados: "+String.Join(", ",missing)+".\r\n\r\nSelecione a pasta do BF4 instalado pela EA ou Steam, que contém bf4.exe.";}
}
}
